# owner: platform
"""Weekly timesheet rows, one per worker, busiest first."""

from typing import Dict, Iterable, List

from hourglass.models import Shift
from collections import defaultdict

def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts to total")
    for item in shifts:
        if not item.worker.strip():
            raise ValueError("shift has a blank worker")

def _totals(shifts: Iterable[Shift]) -> Dict[str, list]:
    totals = defaultdict(lambda: [0, 0])
    for item in shifts:
        entry = totals[item.worker.strip()]
        entry[0] += 1
        entry[1] += item.span.minutes
    return totals

def _row(name: str, count: int, minutes: int) -> str:
    return f"{name}, {count}, {minutes / 60:.1f}"

def timesheet_rows(shifts: List[Shift]) -> List[str]:
    """Lines of 'name, shifts, hours', most hours first."""
    _check(shifts)
    totals = _totals(shifts)
    order = sorted(
        totals, key=lambda name: (-totals[name][1], name)
    )
    return [_row(name, *totals[name]) for name in order]

