# owner: platform
import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span

def make_shift(worker, start, end, when="mon"):
    return Shift(worker, when, Span(start, end))

def busy_week():
    return [
        make_shift("Bob", 480, 540),
        make_shift("Cleo", 480, 720),
        make_shift("Abby", 480, 540, "tue"),
    ]

class TimesheetTests(unittest.TestCase):
    def test_totals_per_worker(self):
        shifts = [
            make_shift("Ana", 480, 750),
            make_shift("Ana", 480, 720, "tue"),
        ]
        rows = timesheet_rows(shifts)
        self.assertEqual(rows, ["Ana, 2, 8.5"])

    def test_busiest_first(self):
        expect = ["Cleo, 1, 4.0", "Abby, 1, 1.0",
                  "Bob, 1, 1.0"]
        rows = timesheet_rows(busy_week())
        self.assertEqual(rows, expect)

    def test_hours_use_one_decimal(self):
        rows = timesheet_rows([make_shift("Ana", 480, 500)])
        self.assertEqual(rows, ["Ana, 1, 0.3"])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    def test_blank_worker_raises(self):
        for blank in ("", "   "):
            with self.assertRaises(ValueError):
                shift = make_shift(blank, 480, 540)
                timesheet_rows([shift])
